  324 	state: QuestionInteractionState,
  325 	action: QuestionInteractionAction,
  326 ): QuestionInteractionState {
  327 	switch (action.type) {
  328 		case "update-answers":
  329 			return { ...state, answers: action.update(state.answers) };
  330 		case "submit":
  331 			return { ...state, submitted: true };
  332 		case "navigate":
  333 			return { ...state, current: action.current };
  334 		case "toggle-collapsed":
  335 			return { ...state, collapsed: !state.collapsed };
  336 		case "drag-start":
  337 			return { ...state, draggingMatch: action.value };
  338 		case "drag-over":
  339 			return { ...state, dragOverRow: action.row };
  340 		case "drag-end":
  341 			return { ...state, draggingMatch: null, dragOverRow: null };
  342 	}
  343 }
