  353 function matchingCorrectness(question: QuestionField, rowIndex: number, choice: string): "correct" | "wrong" | null {
  354 	const correct = question.correctMatches?.[rowIndex];
  355 	if (!correct || !choice) return null;
  356 	return choice.trim().toLowerCase() === correct.trim().toLowerCase() ? "correct" : "wrong";
